    "owner_agent": "LogicMaster",
    "tasks": {
        "CalculateDistanceFromGreyPen": "Calculate the distance from each item to the grey pen.",
        "FindFurthestItem": "Identify which item is furthest from the grey pen based on calculated distances, handling ties by considering their relative positions."
    },
    "orders": [
        {
            "condition": "success",
